async function reservePart(user, partId, woId) {
  assertRole(user, "technician");          // 권한
  const part = await db.part(partId);
  if (part.status !== "in_stock") throw Error("재고 없음"); // 규칙
  await db.tx(t => { t.reserve(partId, woId);   // 쓰기
    t.audit(user.id, "reservePart", { partId, woId }); }); // 감사
}
